      const examples: Example<TomlMetadata>[] = [];
      const claimedFiles = new Set<string>();
      const errors: { path: string; message: string }[] = [];

      // Find meta.toml files from candidates
      const tomlFiles: string[] = [];

      for (const candidate of candidates) {
        const fullPath = path.join(candidate.parentPath, candidate.name);

        if (candidate.isFile()) {
          // Direct file candidate: check if it's a meta.toml
          if (candidate.name === 'meta.toml') {
            tomlFiles.push(fullPath);
          }
        } else if (candidate.isDirectory()) {
          // Directory candidate: look for meta.toml inside
          const metaPath = path.join(fullPath, 'meta.toml');
          try {
            await readFile(metaPath, 'utf-8');
            tomlFiles.push(metaPath);
          } catch {
            // No meta.toml in this directory, skip
          }
        }
      }

      for (const tomlFile of tomlFiles) {
        try {
          const content = await readFile(tomlFile, 'utf-8');
          const metadata = parseSimpleToml(content);

          const exampleDir = path.dirname(tomlFile);

          // Collect all files in the example directory
          const files = collectExampleFiles(exampleDir);

          // Claim all files
          for (const file of files) {
            claimedFiles.add(file);
          }

          examples.push({
            id: metadata.id,
            title: metadata.title,
            description: metadata.description,
            rootPath: exampleDir,
            files: files.map((f) => new ExampleFile({
              absolutePath: f,
              relativePath: path.relative(exampleDir, f),
            })),
            metadata,
            extractorName: 'toml-extractor',
          });
        } catch (err) {
          errors.push({
            path: tomlFile,
            message: `Failed to parse: ${(err as Error).message}`,
          });
        }
      }

      return { examples, errors, claimedFiles };
    },
  };
}

/**
 * Simplified TOML parser for demonstration.
 * In production, use a proper TOML library like @iarna/toml.
 */
function parseSimpleToml(content: string): TomlMetadata {
  const lines = content.split('\n');
  const result: Record<string, string> = {};

  for (const line of lines) {
    // Match: key = "value"
    const match = line.match(/^(\w+)\s*=\s*"(.*)"/);
    if (match) {
      result[match[1]] = match[2];
    }
  }

  if (!result['id'] || !result['title']) {
    throw new Error('TOML must have id and title fields');
  }

  return {
    id: result['id'],
    title: result['title'],
    description: result['description'],
    author: result['author'],
  };
}

function collectExampleFiles(root: string) {
  if (root.endsWith('node_modules')) {
    return [];
  }

  let files: string[] = [];
  const entries = readdirSync(root, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isDirectory()) {
      files = files.concat(
        collectExampleFiles(join(entry.parentPath, entry.name))
      );
    } else {
      files.push(join(entry.parentPath, entry.name));
    }
  }
  return files;
}

```

The **claimed files** mechanism is important: when multiple plugins are active, each extractor claims the files it processes. This prevents the same file from being extracted twice by different plugins.

## Plugins

A **Plugin** is a container that provides one or more capabilities:

| Capability | Purpose |
|-----------|---------|
| **extractor** | Discovers examples from files |
| **validators** | Checks example metadata against rules |
| **schemas** | JSON Schema definitions for metadata and options |
| **commands** | CLI commands the plugin adds |
| **extensions** | File extensions the plugin handles |

Plugins are registered in your config:

```typescript title="functional-examples.config.ts#full-config"
import { createJavaScriptPlugin } from '@functional-examples/javascript';
import { createTestPlugin } from '@functional-examples/test';
import { createDocumentationPlugin } from '@functional-examples/documentation';

export default {
  plugins: [
    createJavaScriptPlugin(),    // extracts from frontmatter or package.json
    createTestPlugin(),          // reads metadata.test for assertions
    createDocumentationPlugin(), // adds doc generation
  ],
};
```

Each plugin operates independently. The scanner calls each plugin's extractor in sequence, passing unclaimed files to subsequent extractors.

## Regions

**Regions** (also called hunks) are named sections within a file, marked with `#region` / `#endregion` comments:

```typescript title="src/regions-demo.ts"
/**
 * ---
 * id: region-markers
 * title: Region Markers Demo
 * ---
 */

import { scan } from 'functional-examples';

// #region setup
const result = await scan();
// #endregion

// #region execution
console.log(result.examples);
// #endregion

```

Regions let you reference specific parts of a file in documentation. Instead of showing an entire file, you can pull just the `setup` region:

```markdown
<%= example('my-example').region('setup') %\>;
```

> [!NOTE]
> There's a zero width space in the above code to prevent it from being processed by eta, copying it directly will not work.

The JavaScript plugin automatically detects `#region` / `#endregion` markers and records their line ranges as hunks on the file.

## The Scanner Pipeline

When you call `scan()` or `scanExamples()`, here's what happens:

1. **Config resolution** — the config file is loaded, plugins are instantiated, and scan patterns are resolved
2. **File discovery** — the scanner globs for files matching `scan.include` patterns (minus `scan.exclude`)
3. **Path mapping** — if `pathMappings` are configured, files are routed to specific extractors by pattern
4. **Extraction** — each plugin's extractor runs against its candidate files, producing examples and claiming files
5. **Validation** — if the config includes a `metadata` schema, each example's metadata is validated against it
6. **Result assembly** — examples, errors, and stats are collected into a `ScanResult`

The result gives you everything you need to generate docs, run tests, or build custom tooling.

## Configuration

Configuration lives in a `functional-examples.config.ts` (or `.json`) file at your project root. It controls:

- **plugins** — which plugins to load
- **scan.root** — base directory for scanning
- **scan.include / scan.exclude** — glob patterns for file discovery
- **pathMappings** — route specific file patterns to specific extractors
- **metadata** — JSON Schema for validating example metadata

See the [Configuration guide](../configuration) for the full reference.

# Snapshot Testing

Snapshot testing compares actual output against a stored reference file. This is useful for verifying that scan results, generated files, or command output haven't changed unexpectedly.

## When to Use Snapshots

| Scenario | Approach |
|----------|----------|
| Simple exit code check | `exitCode: 0` |
| Output contains a substring | `stdout.contains` |
| Exact output match | Snapshot assertion |
| Complex multi-line output | Snapshot assertion |
| Generated file verification | File + snapshot assertion |

Use snapshots when the output is complex enough that inline assertions become unwieldy.

## Defining Snapshot Assertions

Test definitions can include snapshot assertions. Here's a real example:

```json title="examples/greeting/package.json#snapshot-test"
  "functional-examples": {
    "title": "Greeting Function",
    "test": [
      {
        "name": "scan output matches snapshot",
        "steps": [
          {
            "command": "bash ../../scan.sh",
            "assertions": {
              "exitCode": 0
            }
          },
          {
            "command": "true",
            "assertions": {
              "snapshot": {
                "path": "../../output.txt",
                "snapshot": "../../__snapshots__/scan-output.txt"
              }
            }
          }
        ]
      },
      {
        "name": "cleanup",
        "options": {
          "command": "rm -f ../../output.txt"
        },
        "assertions": {
          "exitCode": 0
        }
      }
    ]
  },
```

Or check multiple snapshots:

```yaml
assertions:
  snapshots:
    - path: dist/index.js
      snapshot: __snapshots__/index.js
    - path: dist/types.d.ts
      snapshot: __snapshots__/types.d.ts
```

## First-Run Behavior

On the first run, if the snapshot file doesn't exist, the test runner creates it from the actual output. Subsequent runs compare against the stored snapshot.

## Updating Snapshots

When output intentionally changes, update snapshots with the `-u` flag:

```bash
npx functional-examples test -u
```

This overwrites stored snapshot files with current output.

## Multi-Step Snapshot Workflow

```json title="examples/greeting/package.json#snapshot-test"
  "functional-examples": {
    "title": "Greeting Function",
    "test": [
      {
        "name": "scan output matches snapshot",
        "steps": [
          {
            "command": "bash ../../scan.sh",
            "assertions": {
              "exitCode": 0
            }
          },
          {
            "command": "true",
            "assertions": {
              "snapshot": {
                "path": "../../output.txt",
                "snapshot": "../../__snapshots__/scan-output.txt"
              }
            }
          }
        ]
      },
      {
        "name": "cleanup",
        "options": {
          "command": "rm -f ../../output.txt"
        },
        "assertions": {
          "exitCode": 0
        }
      }
    ]
  },
```

This pattern:
1. Runs the scan and captures output to a file
2. Compares the file against a stored snapshot
3. Cleans up temporary files

The scan script strips non-deterministic output (like timing) before saving:

```bash title="scan.sh"
#!/usr/bin/env bash
# Scan for examples and save output to a file for snapshot comparison

cd "$(dirname "$0")"

# Run the scan and capture output, stripping the timing line (non-deterministic)
npx functional-examples scan | sed '/^Scan completed in/d' > output.txt

```

And here's the stored snapshot it compares against:

```txt title="__snapshots__/scan-output.txt"
Found 2 example(s)

ID                            Title                                   Files     Extractor
------------------------------------------------------------------------------------------
snapshot-greeting             Greeting Function                       1         javascript-extractor
greeting-example              Greeting Function                       2         javascript-extractor


```

## Snapshots for Generated Content

Snapshots are especially powerful for verifying generated files. The [documentation plugin example](../../plugins/documentation) uses a snapshot to verify the markdown output produced by `functional-examples documentation`:

```markdown title="__snapshots__/doc-sample.md"
---
generated: true
---

# Sample for Documentation

A simple example demonstrating documentation generation

## `src/sample.ts`

### Region: `setup`

```typescript
import { readFileSync } from 'node:fs';

/**
 * Read and parse a configuration file.
 */
export function loadConfig(path: string): Record<string, unknown> {
  const content = readFileSync(path, 'utf-8');
  return JSON.parse(content);
}
```

### Region: `usage`

```typescript
// Load configuration from a JSON file
const config = loadConfig('config.json');
console.log('Loaded config:', config);
```


```

This ensures that changes to the documentation template or plugin logic are caught immediately by the test suite.

## Annotating Snapshots for Documentation

Snapshot files can include region tags so documentation can extract specific sections:

```text
#_region scan-result
Found 1 example(s)
...
#_endregion scan-result
```

Documentation can then reference: `<%= example('snapshot-testing').region('scan-result') %>`

## Parser Pipeline Transparency

Region tags in snapshot files are processed by the parser pipeline — they're stripped before comparison. This means you can annotate snapshots with `#_region` tags for documentation without affecting test assertions.

## Anti-Patterns

- **Don't use `--update-snapshots` in CI** — CI should _detect_ drift, not silently fix it
- **Don't snapshot non-deterministic output** — timestamps, random IDs, and absolute paths make snapshots flaky
- **Don't use snapshots for simple checks** — `stdout.contains` is more resilient to formatting changes

**See also:** [Test Plugin](../../plugins/test) for the full assertion reference, [CI Integration](../ci-integration) for running snapshot tests in pipelines.

# Plugins

Plugins are the primary extension mechanism in functional-examples. Each plugin provides extractors, validators, commands, or schemas. This guide covers the built-in plugins, when to reach for each one, and how to compose them.

## JavaScript Plugin

**Package:** `@functional-examples/javascript`

The JavaScript plugin extracts examples from `.ts`, `.js`, `.tsx`, `.jsx`, `.mjs`, `.cjs`, `.mts`, and `.cts` files. It supports two extraction modes:

**Single-file (frontmatter):** Individual source files with YAML frontmatter in comment blocks. The frontmatter provides `id`, `title`, and any custom metadata. The plugin also detects `#region` / `#endregion` markers for referencing specific code sections.

Here's a single-file example:

```typescript title="src/getting-started.ts"
// ---
// id: getting-started
// title: Getting Started
// description: A simple example demonstrating frontmatter metadata extraction
// tags:
//   - beginner
//   - tutorial
// ---

/**
 * A simple greeting function.
 *
 * @param name - The name to greet
 * @returns A greeting message
 */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

// Example usage of the greet function
const message = greet('World');
console.log(message); // Output: Hello, World!

```

**Multi-file (package.json):** Directories with a `package.json` that provides metadata. The plugin reads `name` (for id), `description`, `keywords`, and custom fields from the `functional-examples` key. It traces entry points (`main`, `module`, `exports`) to discover which files belong to the example.

**When to use it:**

- Your examples are TypeScript or JavaScript (single or multi-file)
- You want metadata co-located with the code
- You want region markers for referencing specific code sections
- You want multi-file examples with automatic entry point tracing

> **Full guide →** [JavaScript Plugin](../../plugins/javascript) — frontmatter syntax, region markers, package.json mode, and all configuration options.

## YAML Manifest Plugin

**Package:** `@functional-examples/yaml-manifest`

The YAML manifest plugin discovers examples via `meta.yml` files in directories. Each `meta.yml` declares the example's metadata, and all sibling files become part of the example.

**When to use it:**

- Your examples span multiple files
- You work with non-JS/TS files (Python, Go, Rust, etc.)
- You want metadata separate from source code
- You need complex metadata structures

> **Full guide →** [YAML Manifest Plugin](../../plugins/yaml-manifest) — meta.yml field reference, directory discovery, and when to choose YAML vs JavaScript.

## Test Plugin

**Package:** `@functional-examples/test`

The test plugin adds testing capabilities. It reads test definitions from `metadata.test` on any scanned example — regardless of which extractor produced it. The test plugin doesn't extract examples itself; it operates on metadata populated by other plugins.

For JavaScript plugin examples using package.json, test definitions live under the `functional-examples.test` key:

```json title="package.json"
{
  "name": "@examples/test-plugin-example",
  "private": true,
  "type": "module",
  "description": "Demonstrates the test plugin with command execution and assertions",
  "dependencies": {
    "functional-examples": "workspace:*",
    "@functional-examples/javascript": "workspace:*",
    "@functional-examples/test": "workspace:*"
  },
  "functional-examples": {
    "title": "Test Plugin Example",
    "tags": ["testing", "assertions", "commands"]
  }
}

```

For frontmatter-based examples, you could add a `test` field to the YAML metadata. For YAML manifest examples, add it to `meta.yml`. The test plugin doesn't care where the metadata came from — it just validates and runs whatever it finds in `metadata.test`.

Run tests with:

```bash
npx functional-examples test
```

**When to use it:**

- You want CI verification that examples actually run
- You need to assert exit codes, stdout, or stderr patterns
- You want regression testing for example code

> **Full guide →** [Test Plugin](../../plugins/test) — full assertion reference, multi-step tests, snapshots, and reporter options.

## Documentation Plugin

**Package:** `@functional-examples/documentation`

The documentation plugin generates markdown documentation from scanned examples. It provides:

- Template-based doc generation (`functional-examples generate`)
- Prose rendering (expanding `file()` and `region()` references in README.md files)
- Guide hydration (expanding cross-example references in standalone guides)

**When to use it:**

- You want auto-generated API docs from example code
- You write guides that reference live example files
- You need consistent documentation format across many examples

> **Full guide →** [Documentation Plugin](../../plugins/documentation) — template system, prose helpers, and guide rendering.

## Multi-Plugin Setup

You can combine multiple plugins. When doing so, use **pathMappings** to route files to the right extractor and avoid conflicts:

```json title="functional-examples.config.json"
{
  "$schema": "./.functional-examples/schema.json",
  "scan": {
    "include": ["src/**/*", "tutorials/*"],
    "exclude": ["**/node_modules/**"]
  },
  "pathMappings": [
    {
      "pattern": "src/**",
      "extractor": "javascript-extractor"
    },
    {
      "pattern": "tutorials/**",
      "extractor": "meta-yml"
    }
  ]
}

```

Path mappings use glob patterns to assign files to specific extractors by name. Files that match a mapping are only sent to the specified extractor. Unmapped files are sent to all extractors.

## Custom Extractors

When the built-in plugins don't fit your metadata format, write a custom extractor. An extractor is a function that receives file candidates and returns examples.

Here's a complete custom extractor that reads TOML metadata files:

```typescript title="toml-extractor.ts"
/**
 * Custom TOML-based extractor example.
 *
 * This demonstrates how to create your own extractor that:
 * 1. Scans for a specific file pattern (meta.toml)
 * 2. Parses metadata from that file format
 * 3. Claims files and returns Example objects
 */
import {
  ExampleFile,
  type Example,
  type Extractor,
  type ExtractorResult,
} from 'functional-examples';
import { readdirSync, type Dirent } from 'node:fs';
import { readFile } from 'node:fs/promises';
import path, { join } from 'node:path';

/**
 * Metadata structure for TOML examples.
 * You can define any shape that fits your use case.
 */
export interface TomlMetadata {
  id: string;
  title: string;
  description?: string;
  author?: string;
  [key: string]: unknown;
}

/**
 * Create a custom extractor that reads TOML metadata files.
 *
 * Extractors implement a candidate-based pattern: they're called with
 * pre-filtered candidates (files and directories) and decide which to handle.
 */
export function createTomlExtractor(): Extractor<TomlMetadata> {
  return {
    name: 'toml-extractor',

    async extract(
      candidates: Dirent[]
    ): Promise<ExtractorResult<TomlMetadata>> {
      const examples: Example<TomlMetadata>[] = [];
      const claimedFiles = new Set<string>();
      const errors: { path: string; message: string }[] = [];

      // Find meta.toml files from candidates
      const tomlFiles: string[] = [];

      for (const candidate of candidates) {
        const fullPath = path.join(candidate.parentPath, candidate.name);

        if (candidate.isFile()) {
          // Direct file candidate: check if it's a meta.toml
          if (candidate.name === 'meta.toml') {
            tomlFiles.push(fullPath);
          }
        } else if (candidate.isDirectory()) {
          // Directory candidate: look for meta.toml inside
          const metaPath = path.join(fullPath, 'meta.toml');
          try {
            await readFile(metaPath, 'utf-8');
            tomlFiles.push(metaPath);
          } catch {
            // No meta.toml in this directory, skip
          }
        }
      }

      for (const tomlFile of tomlFiles) {
        try {
          const content = await readFile(tomlFile, 'utf-8');
          const metadata = parseSimpleToml(content);

          const exampleDir = path.dirname(tomlFile);

          // Collect all files in the example directory
          const files = collectExampleFiles(exampleDir);

          // Claim all files
          for (const file of files) {
            claimedFiles.add(file);
          }

          examples.push({
            id: metadata.id,
            title: metadata.title,
            description: metadata.description,
            rootPath: exampleDir,
            files: files.map((f) => new ExampleFile({
              absolutePath: f,
              relativePath: path.relative(exampleDir, f),
            })),
            metadata,
            extractorName: 'toml-extractor',
          });
        } catch (err) {
          errors.push({
            path: tomlFile,
            message: `Failed to parse: ${(err as Error).message}`,
          });
        }
      }

      return { examples, errors, claimedFiles };
    },
  };
}

/**
 * Simplified TOML parser for demonstration.
 * In production, use a proper TOML library like @iarna/toml.
 */
function parseSimpleToml(content: string): TomlMetadata {
  const lines = content.split('\n');
  const result: Record<string, string> = {};

  for (const line of lines) {
    // Match: key = "value"
    const match = line.match(/^(\w+)\s*=\s*"(.*)"/);
    if (match) {
      result[match[1]] = match[2];
    }
  }

  if (!result['id'] || !result['title']) {
    throw new Error('TOML must have id and title fields');
  }

  return {
    id: result['id'],
    title: result['title'],
    description: result['description'],
    author: result['author'],
  };
}

function collectExampleFiles(root: string) {
  if (root.endsWith('node_modules')) {
    return [];
  }

  let files: string[] = [];
  const entries = readdirSync(root, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isDirectory()) {
      files = files.concat(
        collectExampleFiles(join(entry.parentPath, entry.name))
      );
    } else {
      files.push(join(entry.parentPath, entry.name));
    }
  }
  return files;
}

```

And here's how to use it in a scan script:

```typescript title="scan.ts"
/**
 * Scan script using the custom TOML extractor.
 */
import { scan } from 'functional-examples';
import { resolveConfig } from 'functional-examples';
import { createTomlExtractor } from './toml-extractor.js';

async function main() {
  const jsonOutput = process.argv.includes('--json');

  const config = await resolveConfig({
    root: '.',
    plugins: [
      {
        name: 'toml-extractor',
        extractor: createTomlExtractor(),
      },
    ],
    scan: {
      include: ['**/*'],
      exclude: ['**/node_modules/**'],
    },
  });

  const result = await scan({ config });

  if (jsonOutput) {
    console.log(
      JSON.stringify(
        {
          examples: result.examples.map((e) => ({
            id: e.id,
            title: e.title,
            description: e.description,
            files: e.files.map((f) => f.relativePath),
            metadata: e.metadata,
          })),
          errors: result.errors,
          stats: result.stats,
        },
        null,
        2
      )
    );
  } else {
    console.log(`Found ${result.examples.length} TOML example(s):\n`);
    for (const example of result.examples) {
      console.log(`  ${example.id}: ${example.title}`);
      if (example.description) {
        console.log(`    ${example.description}`);
      }
      console.log(
        `    Files: ${example.files.map((f) => f.relativePath).join(', ')}`
      );
      console.log();
    }

    if (result.errors.length > 0) {
      console.log(`Errors (${result.errors.length}):`);
      for (const error of result.errors) {
        console.log(`  - ${error.path}: ${error.message}`);
      }
    }
  }
}

main().catch(console.error);

```

**Key points for custom extractors:**

- Return `claimedFiles` so other extractors don't process the same files
- Return `errors` for recoverable issues (the scanner collects them)
- Throw for unrecoverable failures
- Use `extractorName` to identify your extractor in results

# Configuration

functional-examples is configured via a config file at your project root. This guide covers every config option, the two config formats, and how to use metadata schemas for validation.

## Config Formats

### TypeScript (recommended)

Create `functional-examples.config.ts`:

```typescript
import { createJavaScriptPlugin } from '@functional-examples/javascript';

export default {
  plugins: [createJavaScriptPlugin()],
  scan: {
    root: 'examples',
    exclude: ['**/node_modules/**', '**/dist/**'],
  },
};
```

TypeScript configs can instantiate plugins directly and benefit from type checking and IDE autocompletion.

### JSON

Create `functional-examples.config.json`:

```json title="functional-examples.config.json"
{
  "$schema": "./.functional-examples/schema.json",
  "scan": {
    "include": ["snippets/**/*"],
    "exclude": ["**/*.test.*", "**/*.spec.*"]
  },
  "pathMappings": [
    {
      "pattern": "**/legacy/**",
      "extractor": "meta-yml"
    }
  ],
  "metadata": {
    "type": "object",
    "properties": {
      "id": {
        "type": "string",
        "description": "Unique identifier for the example"
      },
      "title": {
        "type": "string",
        "description": "Human-readable title"
      },
      "description": {
        "type": "string",
        "description": "What this example demonstrates"
      },
      "category": {
        "type": "string",
        "enum": ["tutorial", "recipe", "reference", "advanced"],
        "description": "Example category for filtering"
      },
      "tags": {
        "type": "array",
        "items": { "type": "string" },
        "description": "Tags for search and filtering"
      }
    },
    "required": ["id", "title", "category"]
  }
}

```

JSON configs are useful when you don't want a build step, work with non-JS tooling, or want machine-editable configuration. Plugins are auto-detected from your `package.json` dependencies.

## Scan Options

### `scan.root`

Base directory for scanning, relative to the config file. Defaults to the current directory.

```typescript
scan: {
  root: 'examples', // only scan under examples/
}
```

### `scan.include`

Glob patterns for files to include. If omitted, all files under the root are candidates.

```typescript
scan: {
  include: ['snippets/**/*', 'tutorials/**/*'],
}
```

### `scan.exclude`

Glob patterns for files to exclude. Always exclude `node_modules` and build artifacts:

```typescript
scan: {
  exclude: ['**/node_modules/**', '**/dist/**', '**/*.test.*'],
}
```

## Path Mappings

When using multiple plugins, **pathMappings** route specific file patterns to specific extractors. This prevents conflicts when two extractors might both try to claim the same file.

```typescript
pathMappings: [
  { pattern: 'src/**', extractor: 'javascript-extractor' },
  { pattern: 'tutorials/**', extractor: 'meta-yml' },
]
```

Each mapping has:
- **pattern** — a glob pattern matched against relative file paths
- **extractor** — the `extractorName` of the target extractor

Files matching a mapping are *only* sent to the specified extractor. Unmapped files are sent to all extractors.

## Metadata Schema

You can enforce metadata standards using a JSON Schema in your config. Every scanned example's metadata is validated against it:

```json title="functional-examples.config.json"
{
  "$schema": "./.functional-examples/schema.json",
  "scan": {
    "include": ["src/**/*"],
    "exclude": ["**/node_modules/**", "**/dist/**"]
  },
  "metadata": {
    "type": "object",
    "properties": {
      "category": {
        "type": "string",
        "description": "Category for organizing examples"
      },
      "difficulty": {
        "type": "string",
        "enum": ["beginner", "intermediate", "advanced"],
        "description": "Difficulty level"
      }
    },
    "required": ["category", "difficulty"]
  }
}

```

When an example's metadata doesn't match the schema, the scanner reports a validation error. Here's an example that passes validation:

```typescript title="src/valid-example.ts"
// ---
// id: valid-example
// title: Valid Example
// description: This example has all required metadata fields
// category: tutorials
// difficulty: beginner
// ---

/**
 * This example passes validation because it includes
 * both `category` and `difficulty` fields.
 */
export function example() {
  console.log('This example has valid metadata!');
}

```

And one that fails because it's missing required fields:

```typescript title="src/missing-fields.ts"
// ---
// id: missing-fields
// title: Missing Required Fields
// description: This example is missing category and difficulty
// ---

/**
 * This example will produce validation errors because
 * it's missing the required `category` and `difficulty` fields.
 *
 * Run `npx functional-examples scan` to see the validation errors.
 */
export function example() {
  console.log('This example is missing required metadata!');
}

```

## Region Config

functional-examples can extract `#region` / `#endregion` hunks from source files without any plugin. The `region` config block controls the marker keywords and which file extensions are recognised.

```typescript
export default {
  region: {
    startTag: 'region',    // default
    endTag: 'endregion',   // default
    fileExtensionMap: {
      // override or extend the built-in map
      '.vue': [/\/\/\s*{token}\s+(\w+)/],
    },
  },
};
```

`fileExtensionMap` values can be `RegExp` literals (recommended in TypeScript configs) or pattern strings — the `{token}` placeholder is replaced with the configured `startTag` or `endTag` at scan time, and the first capturing group captures the region ID.

User-supplied entries are merged over the defaults; the defaults cover these extensions out of the box:

